function renderCamera(){cc.clearRect(0,0,W,H);photoScene(cc);cc.fillStyle='#344c3526';cc.fillRect(0,0,W,frame.y);cc.fillRect(0,frame.y+frame.h,W,H-frame.y-frame.h);cc.fillRect(0,frame.y,frame.x,frame.h);cc.fillRect(frame.x+frame.w,frame.y,frame.x,frame.h);if(grid){for(let i=1;i<3;i++){line(cc,[[frame.x+frame.w*i/3,frame.y],[frame.x+frame.w*i/3,frame.y+frame.h]],'#fffbe94d',1);line(cc,[[frame.x,frame.y+frame.h*i/3],[frame.x+frame.w,frame.y+frame.h*i/3]],'#fffbe94d',1);}}const t=currentTarget(),grade=M.photoGrade(scene,t,frame,t.moment);const cx=t.x,cy=t.y;if(grade.composed){const a=13;cc.strokeStyle='#f9ffdfaa';cc.lineWidth=1.5;cc.beginPath();cc.moveTo(cx-a,cy-a/2);cc.lineTo(cx-a,cy-a);cc.lineTo(cx-a/2,cy-a);cc.moveTo(cx+a/2,cy-a);cc.lineTo(cx+a,cy-a);cc.lineTo(cx+a,cy-a/2);cc.moveTo(cx+a,cy+a/2);cc.lineTo(cx+a,cy+a);cc.lineTo(cx+a/2,cy+a);cc.moveTo(cx-a/2,cy+a);cc.lineTo(cx-a,cy+a);cc.lineTo(cx-a,cy+a/2);cc.stroke();}$('#focus-hint').textContent=scene==='mouse'?(grade.perfect?'奶鼠探出头了。':SCENES.mouse.hint):scene==='together'?(grade.perfect?'看镜头，就是现在。':SCENES.together.hint):grade.composed?'光线正好，按下快门吧。':SCENES.tower.hint;}
function setScene(next){scene=next;cam.x=scene==='mouse'?-70:0;cam.y=0;drag=null;document.querySelectorAll('[data-scene]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.scene===scene)));$('#camera-location').textContent=SCENES[scene].name;$('#scene-note').textContent=SCENES[scene].note;}
document.querySelectorAll('[data-scene]').forEach(b=>b.onclick=()=>setScene(b.dataset.scene));$('#grid-toggle').onclick=()=>{grid=!grid;$('#grid-toggle').setAttribute('aria-pressed',String(grid));};$('#recenter').onclick=()=>{cam.x=0;cam.y=0;};
camera.addEventListener('pointerdown',e=>{if(e.button!==0)return;camera.setPointerCapture(e.pointerId);drag={id:e.pointerId,x:e.clientX,y:e.clientY,oldX:cam.x,oldY:cam.y};camera.parentElement.classList.add('dragging');});camera.addEventListener('pointermove',e=>{if(!drag||drag.id!==e.pointerId)return;const ratio=W/camera.getBoundingClientRect().width;cam.x=M.clamp(drag.oldX+(e.clientX-drag.x)*ratio,-440,390);cam.y=M.clamp(drag.oldY+(e.clientY-drag.y)*ratio,-160,170);});function stopDrag(){drag=null;camera.parentElement.classList.remove('dragging');}camera.addEventListener('pointerup',stopDrag);camera.addEventListener('pointercancel',stopDrag);camera.addEventListener('lostpointercapture',stopDrag);camera.addEventListener('keydown',e=>{const d={ArrowLeft:[24,0],ArrowRight:[-24,0],ArrowUp:[0,20],ArrowDown:[0,-20]}[e.code];if(d){e.preventDefault();cam.x=M.clamp(cam.x+d[0],-440,390);cam.y=M.clamp(cam.y+d[1],-160,170);}if(e.code==='Enter'){e.preventDefault();snap();}});
function displayPhoto(photo){selectedPhoto=photo;$('#photo-location').textContent=photo.location+' · '+photo.date;$('#photo-title').textContent=photo.title;$('#photo-caption').textContent=photo.note;$('#photo-preview').src=photo.image;$('#photo-preview').alt=photo.title;$('#download-photo').href=photo.image;$('#download-photo').download='奶蛙校园-'+photo.date.replace(/[:/ ]/g,'-')+'-'+photo.scene+'.jpg';$('#photo-dialog').showModal();}
function updateAlbumBadge(){$('#album-count').textContent=photos.length;$('#recent-photo').innerHTML=photos.length?'<img src="'+photos[0].image+'" alt="最近拍下的校园照片">':'<span>还没拍照</span>';}
function snap(){if(view!=='camera'||snapping||$('#photo-dialog').open)return;if(!assetsReady){toast('相机准备中，马上就好。');return;}snapping=true;const clean=document.createElement('canvas');clean.width=W;clean.height=H;photoScene(clean.getContext('2d'));const out=document.createElement('canvas');out.width=800;out.height=600;const cx=out.getContext('2d');rect(cx,0,0,800,600,'#fffdf4');cx.drawImage(clean,frame.x,frame.y,frame.w,frame.h,18,18,764,510);const target=currentTarget(),grade=M.photoGrade(scene,target,frame,target.moment),now=new Date(),date=now.toLocaleDateString('zh-CN',{month:'2-digit',day:'2-digit'})+' '+now.toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'});label(cx,SCENES[scene].name,32,562,17,'#70845d');label(cx,'NAIWA / '+date,766,562,12,'#a4ad91','right');const photo={id:Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,6),scene,title:grade.title,note:grade.note,location:SCENES[scene].name,date,image:out.toDataURL('image/jpeg',.85)};photos=[photo,...photos].slice(0,12);let stored=save(':photos',photos);while(!stored&&photos.length>1){photos.pop();stored=save(':photos',photos);}if(!stored)toast('这次照片先留在页面里，也可以点保存。');updateAlbumBadge();tone('photo');window.dispatchEvent(new CustomEvent('mini:result',{detail:{kind:'photo',score:grade.perfect?1:0}}));$('#camera-flash').classList.add('active');setTimeout(()=>$('#camera-flash').classList.remove('active'),80);setTimeout(()=>{snapping=false;if(view==='camera')displayPhoto(photo);},240);}
$('#shutter').onclick=snap;$('#recent-photo').onclick=()=>photos.length?displayPhoto(photos[0]):toast('先拍下第一张校园照片。');$('#close-photo').onclick=()=>$('#photo-dialog').close();$('#keep-shooting').onclick=()=>{if($('#photo-dialog').open)$('#photo-dialog').close();navigate('camera');};$('#photo-dialog').addEventListener('click',e=>{if(e.target===$('#photo-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});
function renderAlbum(){const host=$('#album-grid');host.innerHTML=photos.length?photos.map((p,i)=>'<button class="photo-card" data-photo="'+i+'" style="--tilt:'+(i%3===0?-2:i%3===1?1.5:-.7)+'deg"><img src="'+p.image+'" alt="'+esc(p.title)+'"><strong>'+esc(p.title)+'</strong><small>'+esc(p.location+' · '+p.date)+'</small></button>').join(''):'<div class="empty-album"><span>▧</span><p>第一张，留给今天。</p><button class="inline-link" id="empty-camera">拿起相机 ↗</button></div>';host.querySelectorAll('[data-photo]').forEach(b=>b.onclick=()=>displayPhoto(photos[Number(b.dataset.photo)]));const empty=$('#empty-camera');if(empty)empty.onclick=()=>navigate('camera');}
function tick(now){const dt=lastTime?Math.min(60,Math.max(0,now-lastTime)):0;lastTime=now;if(!document.hidden)clock+=dt;animateBasket(dt);if(view==='basket')renderBasket();else if(view==='camera')renderCamera();requestAnimationFrame(tick);}
updateBasketUI();updateAlbumBadge();requestAnimationFrame(tick);
